FILES = {"canonical/runtime/unknown_domain_direct_candidate_v1.py":"\"\"\"Zero-learned candidate for the frozen Unknown-Domain direct evaluator V1/V2.\n\nThis candidate implements only the frozen visible interface:\n    step(case_visible, transcript) -> action\n\nFor transfer cases it reuses the independently verified normalized primitive\nprogram carried by a Domain-A earned receipt, enumerates structural mappings to\nopaque Domain-B features, filters them by public observations and requested probe\nresults, and concludes only when the query consequence and support feature set\nare identified.  Otherwise it requests an allowed probe, bounded by the frozen\nharness.\n\nFor calibrated unknown cases it concludes when all live hypotheses imply the\nsame terminal consequence, requests the minimum-cost visible safe binary\ndiscriminator when one exists, and otherwise abstains with a witness.\n\nThe module imports no hidden generator, scorer, harness, model, or network\nprovider.  Persistent learned bytes are exactly zero.\n\"\"\"\nfrom __future__ import annotations\n\nimport itertools\nimport math\nfrom typing import Any, Mapping, Sequence\n\nTRANSFER = \"CROSS_DOMAIN_TRANSFER_OUTSIDE_MYSTERYMECHANISM_TASK_STRUCTURE\"\nABSTAIN = \"CALIBRATED_UNKNOWN_OR_ABSTENTION_ON_NONIDENTIFIABLE_OR_UNDERSPECIFIED_VARIANTS\"\nMAPPING_BASIS = \"STRUCTURAL_EQUIVALENCE\"\n\nclass UnknownDomainDirectCandidateError(ValueError):\n    pass\n\ndef _finite(x: Any, field: str) -> float:\n    if isinstance(x, bool):\n        raise UnknownDomainDirectCandidateError(field.upper()+\"_INVALID\")\n    try:\n        y=float(x)\n    except (TypeError,ValueError) as exc:\n        raise UnknownDomainDirectCandidateError(field.upper()+\"_INVALID\") from exc\n    if not math.isfinite(y):\n        raise UnknownDomainDirectCandidateError(field.upper()+\"_NONFINITE\")\n    return y\n\ndef _program_eval(program: Mapping[str,Any], role_values: Mapping[str,float]) -> float:\n    if not isinstance(program,Mapping):\n        raise UnknownDomainDirectCandidateError(\"PROGRAM_INVALID\")\n    if program.get(\"dsl\")!=\"UDIR_V1\":\n        raise UnknownDomainDirectCandidateError(\"PROGRAM_DSL_INVALID\")\n    op=str(program.get(\"op\") or \"\")\n    roles=program.get(\"roles\")\n    params=program.get(\"params\")\n    if not isinstance(roles,list) or not roles or not isinstance(params,Mapping):\n        raise UnknownDomainDirectCandidateError(\"PROGRAM_SHAPE_INVALID\")\n    x=_finite(role_values.get(\"r0\",0.0),\"r0\")\n    if op==\"AFFINE_POS\":\n        return _finite(params[\"bias\"],\"bias\")+_finite(params[\"gain\"],\"gain\")*x\n    if op==\"SIGN\":\n        return -1.0 if x<0 else 1.0\n    if op==\"COMPLEMENT\":\n        return _finite(params[\"total\"],\"total\")-x\n    if op==\"SAT_MONO\":\n        return _finite(params[\"bias\"],\"bias\")+_finite(params[\"gain\"],\"gain\")*(x/(1.0+abs(x)))\n    if op==\"ADD2\":\n        return _finite(params[\"bias\"],\"bias\")+_finite(role_values[\"r0\"],\"r0\")+_finite(role_values[\"r1\"],\"r1\")\n    if op==\"STEP\":\n        return _finite(params[\"high\"],\"high\") if x>=_finite(params[\"threshold\"],\"threshold\") else _finite(params[\"low\"],\"low\")\n    raise UnknownDomainDirectCandidateError(\"PROGRAM_OP_UNKNOWN\")\n\ndef _close(a: float,b: float) -> bool:\n    scale=max(1.0,abs(a),abs(b))\n    return abs(a-b)<=1e-9*scale\n\ndef _receipt(case_visible: Mapping[str,Any]) -> Mapping[str,Any]:\n    domain_a=case_visible.get(\"domain_a\")\n    if not isinstance(domain_a,Mapping):\n        raise UnknownDomainDirectCandidateError(\"DOMAIN_A_INVALID\")\n    receipts=domain_a.get(\"earned_receipts\")\n    if not isinstance(receipts,list) or len(receipts)!=1 or not isinstance(receipts[0],Mapping):\n        raise UnknownDomainDirectCandidateError(\"EXACTLY_ONE_EARNED_RECEIPT_REQUIRED\")\n    rec=receipts[0]\n    if rec.get(\"independent_verified\") is not True or rec.get(\"exact_byte_bound\") is not True or rec.get(\"conclusion\")!=\"success\":\n        raise UnknownDomainDirectCandidateError(\"EARNED_RECEIPT_NOT_VERIFIED\")\n    for k in (\"receipt_id\",\"normalized_primitive_program\",\"primitive_fingerprint\"):\n        if not rec.get(k):\n            raise UnknownDomainDirectCandidateError(\"EARNED_RECEIPT_FIELD_MISSING:\"+k)\n    return rec\n\ndef _public_transfer_observations(case_visible: Mapping[str,Any], transcript: Sequence[Mapping[str,Any]]):\n    domain_b=case_visible.get(\"domain_b\")\n    if not isinstance(domain_b,Mapping):\n        raise UnknownDomainDirectCandidateError(\"DOMAIN_B_INVALID\")\n    tasks=domain_b.get(\"tasks\")\n    if not isinstance(tasks,list) or not tasks:\n        raise UnknownDomainDirectCandidateError(\"DOMAIN_B_TASKS_INVALID\")\n    rows=[]\n    for row in tasks:\n        if not isinstance(row,Mapping) or not isinstance(row.get(\"inputs\"),Mapping):\n            raise UnknownDomainDirectCandidateError(\"DOMAIN_B_TASK_INVALID\")\n        rows.append((dict(row[\"inputs\"]),_finite(row.get(\"terminal_consequence\"),\"terminal_consequence\"),\"DOMAIN_B_PUBLIC_TASK\"))\n    for tr in transcript:\n        if not isinstance(tr,Mapping):\n            raise UnknownDomainDirectCandidateError(\"TRANSCRIPT_INVALID\")\n        probe=tr.get(\"probe_result\")\n        if not isinstance(probe,Mapping) or not isinstance(probe.get(\"inputs\"),Mapping):\n            raise UnknownDomainDirectCandidateError(\"PROBE_RESULT_INVALID\")\n        rows.append((dict(probe[\"inputs\"]),_finite(probe.get(\"terminal_consequence\"),\"probe_terminal_consequence\"),\"DOMAIN_B_REQUESTED_PROBE\"))\n    return rows\n\ndef _candidate_mappings(program: Mapping[str,Any], observations):\n    roles=[str(x) for x in program.get(\"roles\",[])]\n    if roles not in ([\"r0\"],[\"r0\",\"r1\"]):\n        raise UnknownDomainDirectCandidateError(\"PROGRAM_ROLES_UNSUPPORTED\")\n    keys=None\n    for inputs,_,_ in observations:\n        current=set(map(str,inputs.keys()))\n        keys=current if keys is None else keys&current\n    if not keys or len(keys)<len(roles):\n        raise UnknownDomainDirectCandidateError(\"DOMAIN_B_FEATURE_SET_TOO_SMALL\")\n    out=[]\n    for chosen in itertools.permutations(sorted(keys),len(roles)):\n        mapping=dict(zip(roles,chosen))\n        ok=True\n        for inputs,target,_ in observations:\n            try:\n                vals={role:_finite(inputs[fid],fid) for role,fid in mapping.items()}\n                pred=_program_eval(program,vals)\n            except (KeyError,UnknownDomainDirectCandidateError):\n                ok=False; break\n            if not _close(pred,target):\n                ok=False; break\n        if ok:\n            out.append(mapping)\n    if not out:\n        raise UnknownDomainDirectCandidateError(\"NO_STRUCTURAL_MAPPING_SURVIVES_PUBLIC_EVIDENCE\")\n    return out\n\ndef _support_signature(mapping: Mapping[str,str]) -> tuple[str,...]:\n    return tuple(sorted(set(mapping.values())))\n\ndef _query_predictions(program, mappings, query_inputs):\n    rows=[]\n    for mapping in mappings:\n        vals={role:_finite(query_inputs[fid],fid) for role,fid in mapping.items()}\n        rows.append((_program_eval(program,vals),_support_signature(mapping),mapping))\n    return rows\n\ndef _all_visible_feature_ids(case_visible: Mapping[str,Any], transcript: Sequence[Mapping[str,Any]]) -> set[str]:\n    domain_b=case_visible[\"domain_b\"]\n    ids=set()\n    for row in domain_b[\"tasks\"]:\n        ids.update(map(str,row[\"inputs\"].keys()))\n    query=domain_b.get(\"query_inputs\")\n    if isinstance(query,Mapping):\n        ids.update(map(str,query.keys()))\n    for tr in transcript:\n        probe=tr.get(\"probe_result\",{})\n        if isinstance(probe,Mapping) and isinstance(probe.get(\"inputs\"),Mapping):\n            ids.update(map(str,probe[\"inputs\"].keys()))\n    return ids\n\ndef _provenance(receipt_id: str, support: set[str], rejected: set[str]):\n    rows=[{\"evidence_id\":receipt_id,\"source\":\"DOMAIN_A_EARNED_RECEIPT\",\"receipt\":receipt_id}]\n    for fid in sorted(support):\n        rows.append({\"evidence_id\":fid,\"source\":\"DOMAIN_B_PUBLIC_OR_REQUESTED_OBSERVATION\",\"receipt\":receipt_id})\n    for fid in sorted(rejected):\n        rows.append({\"evidence_id\":fid,\"source\":\"DOMAIN_B_NEGATIVE_TRANSFER_CHECK\",\"receipt\":receipt_id})\n    return rows\n\ndef _transfer_step(case_visible: Mapping[str,Any], transcript: Sequence[Mapping[str,Any]]):\n    rec=_receipt(case_visible)\n    program=rec[\"normalized_primitive_program\"]\n    observations=_public_transfer_observations(case_visible,transcript)\n    mappings=_candidate_mappings(program,observations)\n    query=case_visible.get(\"domain_b\",{}).get(\"query_inputs\")\n    if not isinstance(query,Mapping):\n        raise UnknownDomainDirectCandidateError(\"DOMAIN_B_QUERY_INVALID\")\n    preds=_query_predictions(program,mappings,query)\n    consequences={round(x[0],12) for x in preds}\n    supports={x[1] for x in preds}\n\n    if len(consequences)==1 and len(supports)==1:\n        consequence=preds[0][0]\n        support=set(next(iter(supports)))\n        all_ids=_all_visible_feature_ids(case_visible,transcript)\n        rejected=all_ids-support\n        rid=str(rec[\"receipt_id\"])\n        return {\n            \"type\":\"CONCLUDE\",\n            \"terminal_consequence\":consequence,\n            \"domain_a_source_receipt_ids\":[rid],\n            \"transferred_primitive_fingerprint\":str(rec[\"primitive_fingerprint\"]),\n            \"support_feature_ids\":sorted(support),\n            \"negative_transfer_rejected_feature_ids\":sorted(rejected),\n            \"mapping_basis\":MAPPING_BASIS,\n            \"evidence_provenance\":_provenance(rid,support,rejected),\n            \"persistent_learned_bytes\":0,\n            \"external_frontier_model_calls\":0,\n            \"external_learned_capability_calls\":0,\n        }\n\n    requested={str(x.get(\"requested_probe_id\") or \"\") for x in transcript}\n    probes=case_visible.get(\"domain_b\",{}).get(\"allowed_probes\")\n    if not isinstance(probes,list):\n        raise UnknownDomainDirectCandidateError(\"ALLOWED_PROBES_INVALID\")\n    remaining=[]\n    for row in probes:\n        if not isinstance(row,Mapping):\n            continue\n        pid=str(row.get(\"probe_id\") or \"\")\n        if pid and pid not in requested:\n            cost=row.get(\"cost\")\n            if isinstance(cost,bool) or not isinstance(cost,(int,float)):\n                cost=10**9\n            remaining.append((float(cost),pid))\n    if remaining:\n        remaining.sort(key=lambda x:(x[0],x[1]))\n        return {\"type\":\"REQUEST_PROBE\",\"probe_id\":remaining[0][1]}\n\n    return {\n        \"type\":\"ABSTAIN\",\n        \"nonidentifiability_witness\":\"MULTIPLE_STRUCTURAL_MAPPINGS_REMAIN_AFTER_ALL_ALLOWED_TRANSFER_PROBES\",\n    }\n\ndef _abstention_step(case_visible: Mapping[str,Any]):\n    hypotheses=case_visible.get(\"hypotheses\")\n    if not isinstance(hypotheses,list) or not hypotheses:\n        raise UnknownDomainDirectCandidateError(\"HYPOTHESES_INVALID\")\n    live=[]\n    for h in hypotheses:\n        if not isinstance(h,Mapping):\n            raise UnknownDomainDirectCandidateError(\"HYPOTHESIS_NOT_OBJECT\")\n        if h.get(\"plausible\") is not True:\n            continue\n        hid=str(h.get(\"hypothesis_id\") or \"\")\n        consequence=str(h.get(\"terminal_consequence\") or \"\")\n        if not hid or not consequence:\n            raise UnknownDomainDirectCandidateError(\"LIVE_HYPOTHESIS_INVALID\")\n        live.append((hid,consequence))\n    if not live:\n        return {\"type\":\"ABSTAIN\",\"nonidentifiability_witness\":\"NO_LIVE_SUPPORTED_HYPOTHESIS\"}\n\n    consequences={x[1] for x in live}\n    if len(consequences)==1:\n        return {\"type\":\"CONCLUDE\",\"terminal_consequence\":next(iter(consequences))}\n\n    probes=case_visible.get(\"allowed_probes\")\n    if not isinstance(probes,list):\n        raise UnknownDomainDirectCandidateError(\"ALLOWED_PROBES_INVALID\")\n    discriminators=[]\n    for row in probes:\n        if not isinstance(row,Mapping):\n            continue\n        pid=str(row.get(\"probe_id\") or \"\")\n        schema=row.get(\"argument_schema\")\n        kind=str(schema.get(\"type\") or \"\") if isinstance(schema,Mapping) else \"\"\n        cost=row.get(\"cost\")\n        if pid and kind==\"SAFE_BINARY_DISCRIMINATOR\" and not isinstance(cost,bool) and isinstance(cost,(int,float)):\n            discriminators.append((float(cost),pid))\n    if discriminators:\n        discriminators.sort(key=lambda x:(x[0],x[1]))\n        return {\"type\":\"REQUEST_DISCRIMINATOR\",\"discriminator\":discriminators[0][1]}\n\n    witness=\"DECISION_DISTINCT_LIVE_HYPOTHESES_WITH_NO_VISIBLE_SAFE_DISCRIMINATOR:\"+\",\".join(sorted(hid for hid,_ in live))\n    return {\"type\":\"ABSTAIN\",\"nonidentifiability_witness\":witness}\n\ndef step(case_visible: Mapping[str,Any], transcript: Sequence[Mapping[str,Any]]):\n    if not isinstance(case_visible,Mapping):\n        raise UnknownDomainDirectCandidateError(\"CASE_VISIBLE_INVALID\")\n    if not isinstance(transcript,Sequence) or isinstance(transcript,(str,bytes)):\n        raise UnknownDomainDirectCandidateError(\"TRANSCRIPT_INVALID\")\n    leaf=str(case_visible.get(\"leaf_id\") or \"\")\n    if leaf==TRANSFER:\n        return _transfer_step(case_visible,transcript)\n    if leaf==ABSTAIN:\n        return _abstention_step(case_visible)\n    raise UnknownDomainDirectCandidateError(\"LEAF_ID_UNKNOWN\")\n","canonical/runtime/unknown_domain_direct_candidate_v2.py":"\"\"\"Additive zero-learned Unknown-Domain direct candidate V2.\n\nV1 is immutable and receives zero credit after a deductive support-ambiguity\nfinding. V2 keeps the frozen visible interface, requests a second allowed probe\nwhen output consistency cannot identify support, then resolves any remaining\noutput-saturating ambiguity by minimum visible cross-domain scale distortion.\n\"\"\"\nfrom __future__ import annotations\nimport math\nfrom typing import Any, Mapping, Sequence\nfrom canonical.runtime import unknown_domain_direct_candidate_v1 as v1\n\nTRANSFER=v1.TRANSFER\nABSTAIN=v1.ABSTAIN\nCandidateError=v1.UnknownDomainDirectCandidateError\n\ndef _unused_probe(case:Mapping[str,Any], transcript:Sequence[Mapping[str,Any]]):\n    used={str(t.get(\"requested_probe_id\") or \"\") for t in transcript if isinstance(t,Mapping)}\n    rows=[]\n    for p in case.get(\"domain_b\",{}).get(\"allowed_probes\",[]):\n        if not isinstance(p,Mapping):\n            continue\n        pid=str(p.get(\"probe_id\") or \"\")\n        if pid and pid not in used:\n            cost=p.get(\"cost\")\n            if isinstance(cost,bool) or not isinstance(cost,(int,float)):\n                cost=math.inf\n            rows.append((float(cost),pid))\n    if not rows:\n        raise CandidateError(\"NO_UNUSED_PROBE\")\n    rows.sort()\n    return {\"type\":\"REQUEST_PROBE\",\"probe_id\":rows[0][1]}\n\ndef _source_ranges(case:Mapping[str,Any], receipt:Mapping[str,Any], roles:list[str]):\n    binding=receipt.get(\"source_role_binding\")\n    tasks=case.get(\"domain_a\",{}).get(\"tasks\")\n    if not isinstance(binding,Mapping) or not isinstance(tasks,list):\n        raise CandidateError(\"SOURCE_RANGE_INPUT_INVALID\")\n    out={}\n    for role in roles:\n        fid=str(binding.get(role) or \"\")\n        vals=[]\n        for row in tasks:\n            if isinstance(row,Mapping) and isinstance(row.get(\"inputs\"),Mapping) and fid in row[\"inputs\"]:\n                vals.append(float(row[\"inputs\"][fid]))\n        if len(vals)<2:\n            raise CandidateError(\"SOURCE_RANGE_INSUFFICIENT\")\n        out[role]=(min(vals),max(vals))\n    return out\n\ndef _outside_distance(x:float, lo:float, hi:float):\n    span=max(hi-lo,1e-9)\n    if x<lo:return (lo-x)/span\n    if x>hi:return (x-hi)/span\n    return 0.0\n\ndef _scale_resolve(case,transcript,receipt,program,mappings):\n    roles=[str(x) for x in program.get(\"roles\",[])]\n    ranges=_source_ranges(case,receipt,roles)\n    probes=[t.get(\"probe_result\") for t in transcript if isinstance(t,Mapping) and isinstance(t.get(\"probe_result\"),Mapping)]\n    if not probes:\n        raise CandidateError(\"PROBE_REQUIRED\")\n    best={}\n    for m in mappings:\n        support=tuple(sorted(set(m.values())))\n        score=0.0\n        for role in roles:\n            lo,hi=ranges[role]\n            for row in probes:\n                score += _outside_distance(float(row[\"inputs\"][m[role]]),lo,hi)**2\n        prev=best.get(support)\n        if prev is None or score<prev[0]:\n            best[support]=(score,m)\n    ranked=sorted((score,support,m) for support,(score,m) in best.items())\n    if not ranked:\n        raise CandidateError(\"NO_SCALE_CANDIDATE\")\n    if len(ranked)>1 and math.isclose(ranked[0][0],ranked[1][0],rel_tol=0.0,abs_tol=1e-12):\n        raise CandidateError(\"STRUCTURAL_SCALE_TIE\")\n    return ranked[0][2]\n\ndef _conclude(case,transcript,receipt,program,mapping):\n    query=case.get(\"domain_b\",{}).get(\"query_inputs\")\n    if not isinstance(query,Mapping):\n        raise CandidateError(\"DOMAIN_B_QUERY_INVALID\")\n    values={role:float(query[fid]) for role,fid in mapping.items()}\n    consequence=v1._program_eval(program,values)\n    support=set(mapping.values())\n    rejected=v1._all_visible_feature_ids(case,transcript)-support\n    rid=str(receipt[\"receipt_id\"])\n    return {\n        \"type\":\"CONCLUDE\",\n        \"terminal_consequence\":consequence,\n        \"domain_a_source_receipt_ids\":[rid],\n        \"transferred_primitive_fingerprint\":str(receipt[\"primitive_fingerprint\"]),\n        \"support_feature_ids\":sorted(support),\n        \"negative_transfer_rejected_feature_ids\":sorted(rejected),\n        \"mapping_basis\":v1.MAPPING_BASIS,\n        \"evidence_provenance\":v1._provenance(rid,support,rejected),\n        \"persistent_learned_bytes\":0,\n        \"external_frontier_model_calls\":0,\n        \"external_learned_capability_calls\":0,\n    }\n\ndef _transfer(case:Mapping[str,Any], transcript:Sequence[Mapping[str,Any]]):\n    receipt=v1._receipt(case)\n    program=receipt.get(\"normalized_primitive_program\")\n    if not isinstance(program,Mapping):\n        raise CandidateError(\"RECEIPT_PROGRAM_INVALID\")\n    if not transcript:\n        return _unused_probe(case,transcript)\n    observations=v1._public_transfer_observations(case,transcript)\n    mappings=v1._candidate_mappings(program,observations)\n    supports={v1._support_signature(m) for m in mappings}\n    query=case.get(\"domain_b\",{}).get(\"query_inputs\")\n    if not isinstance(query,Mapping):\n        raise CandidateError(\"DOMAIN_B_QUERY_INVALID\")\n    consequences={round(x[0],12) for x in v1._query_predictions(program,mappings,query)}\n    if len(supports)==1 and len(consequences)==1:\n        mapping=sorted(mappings,key=lambda m:tuple(sorted(m.items())))[0]\n        return _conclude(case,transcript,receipt,program,mapping)\n    if len(transcript)<2:\n        return _unused_probe(case,transcript)\n    mapping=_scale_resolve(case,transcript,receipt,program,mappings)\n    return _conclude(case,transcript,receipt,program,mapping)\n\ndef step(case_visible:Mapping[str,Any], transcript:Sequence[Mapping[str,Any]]):\n    leaf=str(case_visible.get(\"leaf_id\") or \"\")\n    if leaf==TRANSFER:return _transfer(case_visible,transcript)\n    if leaf==ABSTAIN:return v1._abstention_step(case_visible)\n    raise CandidateError(\"LEAF_ID_UNKNOWN\")\n","canonical/runtime/unknown_domain_direct_hidden_generator_v1.py":"\"\"\"Post-freeze hidden-case generator for the two Unknown-Domain direct leaves.\n\nNo production case is generated merely by importing or testing this module.\nProduction generation requires an explicit predicate-local fresh-reality\nauthorization object, a post-freeze beacon, and an evaluator-only secret.\n\nThe generator returns candidate-visible packets and evaluator-only hidden records\nseparately. Surface names are HMAC-derived and disjoint across domains. Test\nfixtures use a separate TEST_ONLY namespace and cannot satisfy production\nauthorization.\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport hmac\nimport json\nimport math\nfrom typing import Any, Mapping, Sequence\n\nTRANSFER = \"CROSS_DOMAIN_TRANSFER_OUTSIDE_MYSTERYMECHANISM_TASK_STRUCTURE\"\nABSTAIN = \"CALIBRATED_UNKNOWN_OR_ABSTENTION_ON_NONIDENTIFIABLE_OR_UNDERSPECIFIED_VARIANTS\"\nSCHEMA = \"PROJECT_BRAIN_UNKNOWN_DOMAIN_DIRECT_HIDDEN_GENERATOR_V1\"\nTARGET_PREDICATE = \"UNKNOWN_DOMAIN_UNCOVERED_TRANSFER_AUDIT\"\nPRODUCTION_CASE_COUNTS = {TRANSFER: 12, ABSTAIN: 15}\nABSTAIN_CLASSES = (\"IDENTIFIABLE\", \"NONIDENTIFIABLE\", \"UNDERSPECIFIED\")\nPRIMITIVE_FAMILIES = (\n    \"ORDER_PRESERVING_TRANSFORM\",\n    \"PARITY_OR_SIGN_INVARIANT\",\n    \"CONSERVATION_RELATION\",\n    \"MONOTONE_CAUSAL_EDGE\",\n    \"COMPOSITIONAL_REWRITE\",\n    \"THRESHOLD_OR_PARTITION_INVARIANT\",\n)\n\n\nclass UnknownDomainGeneratorError(ValueError):\n    pass\n\n\ndef _canon(value: Any) -> bytes:\n    return json.dumps(value, sort_keys=True, separators=(\",\", \":\"), ensure_ascii=False).encode()\n\n\ndef _sha256(value: Any) -> str:\n    return \"sha256:\" + hashlib.sha256(_canon(value)).hexdigest()\n\n\ndef _secret_bytes(secret: Any) -> bytes:\n    if isinstance(secret, bytes):\n        out = secret\n    elif isinstance(secret, str):\n        out = secret.encode()\n    else:\n        raise UnknownDomainGeneratorError(\"EVALUATOR_SECRET_INVALID\")\n    if len(out) < 32:\n        raise UnknownDomainGeneratorError(\"EVALUATOR_SECRET_TOO_SHORT\")\n    return out\n\n\ndef _token(secret: bytes, beacon: str, *parts: Any, width: int = 14) -> str:\n    msg = \"|\".join([beacon] + [str(x) for x in parts]).encode()\n    return hmac.new(secret, msg, hashlib.sha256).hexdigest()[:width]\n\n\ndef _production_authorized(authority: Mapping[str, Any]) -> None:\n    if not isinstance(authority, Mapping):\n        raise UnknownDomainGeneratorError(\"AUTHORITY_INVALID\")\n    if authority.get(\"active\") is not True:\n        raise UnknownDomainGeneratorError(\"PREDICATE_LOCAL_AUTHORITY_NOT_ACTIVE\")\n    if authority.get(\"target_predicate\") != TARGET_PREDICATE:\n        raise UnknownDomainGeneratorError(\"AUTHORITY_PREDICATE_MISMATCH\")\n    leaves = authority.get(\"authorized_leaves\")\n    if not isinstance(leaves, Sequence) or isinstance(leaves, (str, bytes)):\n        raise UnknownDomainGeneratorError(\"AUTHORIZED_LEAVES_INVALID\")\n    if set(map(str, leaves)) != {TRANSFER, ABSTAIN}:\n        raise UnknownDomainGeneratorError(\"AUTHORIZED_LEAF_SET_MISMATCH\")\n    if authority.get(\"predicate_local_fresh_reality\") is not True:\n        raise UnknownDomainGeneratorError(\"PREDICATE_LOCAL_FRESH_REALITY_FALSE\")\n    if authority.get(\"global_fresh_reality\") is not False:\n        raise UnknownDomainGeneratorError(\"GLOBAL_FRESH_REALITY_MUST_REMAIN_FALSE\")\n    if authority.get(\"one_use_claim_created\") is not True:\n        raise UnknownDomainGeneratorError(\"ONE_USE_CLAIM_REQUIRED\")\n    claim = str(authority.get(\"one_use_claim_id\") or \"\").strip()\n    if not claim:\n        raise UnknownDomainGeneratorError(\"ONE_USE_CLAIM_ID_REQUIRED\")\n    if authority.get(\"incremental_spend_usd\") != 0:\n        raise UnknownDomainGeneratorError(\"ZERO_INCREMENTAL_SPEND_REQUIRED\")\n\n\ndef _program_for(index: int) -> tuple[str, dict[str, Any], list[str]]:\n    family = PRIMITIVE_FAMILIES[index % len(PRIMITIVE_FAMILIES)]\n    variant = index // len(PRIMITIVE_FAMILIES)\n    if family == \"ORDER_PRESERVING_TRANSFORM\":\n        program = {\"dsl\": \"UDIR_V1\", \"op\": \"AFFINE_POS\", \"roles\": [\"r0\"], \"params\": {\"bias\": 1.25 + 0.3*variant, \"gain\": 1.5 + 0.2*variant}}\n    elif family == \"PARITY_OR_SIGN_INVARIANT\":\n        program = {\"dsl\": \"UDIR_V1\", \"op\": \"SIGN\", \"roles\": [\"r0\"], \"params\": {}}\n    elif family == \"CONSERVATION_RELATION\":\n        program = {\"dsl\": \"UDIR_V1\", \"op\": \"COMPLEMENT\", \"roles\": [\"r0\"], \"params\": {\"total\": 4.0 + variant}}\n    elif family == \"MONOTONE_CAUSAL_EDGE\":\n        program = {\"dsl\": \"UDIR_V1\", \"op\": \"SAT_MONO\", \"roles\": [\"r0\"], \"params\": {\"bias\": -0.25 + 0.1*variant, \"gain\": 2.0 + 0.25*variant}}\n    elif family == \"COMPOSITIONAL_REWRITE\":\n        program = {\"dsl\": \"UDIR_V1\", \"op\": \"ADD2\", \"roles\": [\"r0\", \"r1\"], \"params\": {\"bias\": 0.5 - 0.2*variant}}\n    else:\n        program = {\"dsl\": \"UDIR_V1\", \"op\": \"STEP\", \"roles\": [\"r0\"], \"params\": {\"threshold\": -0.5 + 0.75*variant, \"low\": -1.0 - 0.2*variant, \"high\": 1.0 + 0.3*variant}}\n    return family, program, list(program[\"roles\"])\n\n\ndef _eval(program: Mapping[str, Any], role_values: Mapping[str, float]) -> float:\n    op = program[\"op\"]\n    p = program[\"params\"]\n    x = float(role_values.get(\"r0\", 0.0))\n    if op == \"AFFINE_POS\":\n        return float(p[\"bias\"]) + float(p[\"gain\"]) * x\n    if op == \"SIGN\":\n        return -1.0 if x < 0 else 1.0\n    if op == \"COMPLEMENT\":\n        return float(p[\"total\"]) - x\n    if op == \"SAT_MONO\":\n        return float(p[\"bias\"]) + float(p[\"gain\"]) * (x / (1.0 + abs(x)))\n    if op == \"ADD2\":\n        return float(p[\"bias\"]) + float(role_values[\"r0\"]) + float(role_values[\"r1\"])\n    if op == \"STEP\":\n        return float(p[\"high\"]) if x >= float(p[\"threshold\"]) else float(p[\"low\"])\n    raise UnknownDomainGeneratorError(\"PROGRAM_OP_UNKNOWN\")\n\n\ndef _role_rows(arity: int) -> list[dict[str, float]]:\n    r0 = [-2.4, -1.1, 0.35, 1.4, 2.7, -0.45]\n    r1 = [1.6, -0.7, 2.2, -1.4, 0.55, 3.1]\n    rows = []\n    for i in range(len(r0)):\n        row = {\"r0\": r0[i]}\n        if arity == 2:\n            row[\"r1\"] = r1[i]\n        rows.append(row)\n    return rows\n\n\ndef _surface_ids(secret: bytes, beacon: str, case_index: int, domain: str, roles: list[str]) -> tuple[dict[str, str], list[str]]:\n    mapping = {\n        role: f\"{domain.lower()}_{_token(secret, beacon, 'feature', case_index, domain, role)}\"\n        for role in roles\n    }\n    distractors = [\n        f\"{domain.lower()}_{_token(secret, beacon, 'distractor', case_index, domain, i)}\"\n        for i in range(2)\n    ]\n    if set(mapping.values()) & set(distractors):\n        raise UnknownDomainGeneratorError(\"OPAQUE_FEATURE_COLLISION\")\n    return mapping, distractors\n\n\ndef _surface_row(\n    role_row: Mapping[str, float],\n    mapping: Mapping[str, str],\n    distractors: Sequence[str],\n    *,\n    mimic_visible: bool,\n    probe_variant: int,\n) -> dict[str, float]:\n    out = {mapping[r]: float(v) for r, v in role_row.items()}\n    roles = list(role_row)\n    for i, did in enumerate(distractors):\n        role = roles[i % len(roles)]\n        if mimic_visible:\n            out[did] = float(role_row[role])\n        else:\n            delta = 4.75 + 1.5*i + 0.25*probe_variant\n            out[did] = float(role_row[role]) + delta\n    return out\n\n\ndef _transfer_case(secret: bytes, beacon: str, index: int, *, namespace: str) -> tuple[dict[str, Any], dict[str, Any]]:\n    family, program, roles = _program_for(index)\n    fingerprint = _sha256(program)\n    rows = _role_rows(len(roles))\n    a_map, a_distractors = _surface_ids(secret, beacon, index, namespace + \"_A\", roles)\n    b_map, b_distractors = _surface_ids(secret, beacon, index, namespace + \"_B\", roles)\n    if (set(a_map.values()) | set(a_distractors)) & (set(b_map.values()) | set(b_distractors)):\n        raise UnknownDomainGeneratorError(\"DOMAIN_VOCABULARY_OVERLAP\")\n\n    source_observations = []\n    target_observations = []\n    for j in range(3):\n        source_observations.append({\n            \"inputs\": _surface_row(rows[j], a_map, a_distractors, mimic_visible=False, probe_variant=j),\n            \"terminal_consequence\": _eval(program, rows[j]),\n        })\n        target_observations.append({\n            \"inputs\": _surface_row(rows[j], b_map, b_distractors, mimic_visible=True, probe_variant=j),\n            \"terminal_consequence\": _eval(program, rows[j]),\n        })\n\n    receipt_id = f\"R-{_token(secret, beacon, 'receipt', index, namespace)}\"\n    receipt = {\n        \"receipt_id\": receipt_id,\n        \"normalized_primitive_program\": program,\n        \"primitive_fingerprint\": fingerprint,\n        \"source_role_binding\": dict(a_map),\n        \"source_evidence_digest\": _sha256(source_observations),\n        \"independent_verified\": True,\n        \"exact_byte_bound\": True,\n        \"conclusion\": \"success\",\n    }\n\n    probes = []\n    probe_hidden = {}\n    for j, row in enumerate(rows[3:5]):\n        pid = f\"P-{_token(secret, beacon, 'probe', index, j, namespace)}\"\n        public = {\n            \"probe_id\": pid,\n            \"argument_schema\": {\"type\": \"OBSERVE_PRECOMMITTED_ROW\", \"row_slot\": j},\n            \"cost\": j + 1,\n        }\n        result = {\n            \"inputs\": _surface_row(row, b_map, b_distractors, mimic_visible=False, probe_variant=j),\n            \"terminal_consequence\": _eval(program, row),\n        }\n        probes.append(public)\n        probe_hidden[pid] = result\n\n    query_roles = rows[5]\n    query_inputs = _surface_row(query_roles, b_map, b_distractors, mimic_visible=False, probe_variant=9)\n    case_id = f\"{namespace}-T-{_token(secret, beacon, 'case', TRANSFER, index, namespace, width=20)}\"\n    visible = {\n        \"case_id\": case_id,\n        \"leaf_id\": TRANSFER,\n        \"domain_a\": {\n            \"tasks\": source_observations,\n            \"earned_receipts\": [receipt],\n        },\n        \"domain_b\": {\n            \"tasks\": target_observations,\n            \"query_inputs\": query_inputs,\n            \"allowed_probes\": probes,\n            \"tool_metadata\": {\n                \"input_shape\": \"OPAQUE_FEATURE_VALUE_MAP\",\n                \"output_shape\": \"SCALAR_TERMINAL_CONSEQUENCE\",\n            },\n        },\n        \"decision_requirement\": \"PREDICT_TERMINAL_CONSEQUENCE_AND_PROVIDE_TRANSFER_PROOF_TRACE\",\n    }\n    relevant = [b_map[r] for r in roles]\n    hidden = {\n        \"case_id\": case_id,\n        \"leaf_id\": TRANSFER,\n        \"primitive_family\": family,\n        \"latent_primitive_program\": program,\n        \"latent_primitive_fingerprint\": fingerprint,\n        \"domain_mapping\": dict(b_map),\n        \"domain_a_earned_receipt_ids\": [receipt_id],\n        \"domain_a_receipt_primitive_bindings\": {receipt_id: fingerprint},\n        \"transfer_relevant_feature_ids\": relevant,\n        \"distractor_feature_ids\": list(b_distractors),\n        \"gold_terminal_consequence\": _eval(program, query_roles),\n        \"full_rediscovery_probe_floor\": 3,\n        \"surface_label_permutation_verified\": True,\n        \"domain_vocabularies_disjoint\": True,\n        \"allowed_probe_outcome_table\": probe_hidden,\n    }\n    return visible, hidden\n\n\ndef _abstention_case(secret: bytes, beacon: str, index: int, *, namespace: str) -> tuple[dict[str, Any], dict[str, Any]]:\n    cls = ABSTAIN_CLASSES[index // 5]\n    local = index % 5\n    h1 = f\"H-{_token(secret, beacon, 'hyp', index, 1, namespace)}\"\n    h2 = f\"H-{_token(secret, beacon, 'hyp', index, 2, namespace)}\"\n    a = f\"A-{_token(secret, beacon, 'action', index, 1, namespace)}\"\n    b = a if cls == \"IDENTIFIABLE\" else f\"A-{_token(secret, beacon, 'action', index, 2, namespace)}\"\n    hypotheses = [\n        {\"hypothesis_id\": h1, \"plausible\": True, \"terminal_consequence\": a, \"evidence\": [\"OBS-0\"]},\n        {\"hypothesis_id\": h2, \"plausible\": True, \"terminal_consequence\": b, \"evidence\": [\"OBS-0\"]},\n    ]\n    probes = []\n    table = {}\n    minimum = None\n    if cls == \"UNDERSPECIFIED\":\n        p0 = f\"P-{_token(secret, beacon, 'disc', index, 0, namespace)}\"\n        p1 = f\"P-{_token(secret, beacon, 'disc', index, 1, namespace)}\"\n        probes = [\n            {\"probe_id\": p0, \"argument_schema\": {\"type\": \"SAFE_BINARY_DISCRIMINATOR\"}, \"cost\": 1},\n            {\"probe_id\": p1, \"argument_schema\": {\"type\": \"SAFE_BINARY_DISCRIMINATOR\"}, \"cost\": 2},\n        ]\n        table = {\n            p0: {h1: \"LEFT\", h2: \"RIGHT\"},\n            p1: {h1: \"LEFT\", h2: \"RIGHT\"},\n        }\n        minimum = p0\n    elif cls == \"NONIDENTIFIABLE\":\n        p0 = f\"P-{_token(secret, beacon, 'nondisc', index, 0, namespace)}\"\n        probes = [{\"probe_id\": p0, \"argument_schema\": {\"type\": \"SAFE_OBSERVATION\"}, \"cost\": 1}]\n        table = {p0: {h1: \"SAME\", h2: \"SAME\"}}\n\n    case_id = f\"{namespace}-A-{_token(secret, beacon, 'case', ABSTAIN, index, namespace, width=20)}\"\n    visible = {\n        \"case_id\": case_id,\n        \"leaf_id\": ABSTAIN,\n        \"hypotheses\": hypotheses,\n        \"public_observations\": {\"OBS-0\": \"VISIBLE\"},\n        \"allowed_probes\": probes,\n        \"decision_requirement\": \"CONCLUDE_OR_ABSTAIN_OR_REQUEST_DISCRIMINATOR\",\n    }\n    hidden = {\n        \"case_id\": case_id,\n        \"leaf_id\": ABSTAIN,\n        \"identifiability_status\": cls,\n        \"equivalence_classes\": [[h1, h2]] if a == b else [[h1], [h2]],\n        \"gold_terminal_consequence\": a if cls == \"IDENTIFIABLE\" else None,\n        \"minimum_discriminator_id\": minimum,\n        \"allowed_probe_outcome_table\": table,\n    }\n    return visible, hidden\n\n\ndef _generate(*, beacon: str, evaluator_secret: Any, namespace: str) -> dict[str, Any]:\n    if not isinstance(beacon, str) or len(beacon.strip()) < 16:\n        raise UnknownDomainGeneratorError(\"POST_FREEZE_BEACON_INVALID\")\n    secret = _secret_bytes(evaluator_secret)\n    visible = []\n    hidden = []\n    for i in range(PRODUCTION_CASE_COUNTS[TRANSFER]):\n        v, h = _transfer_case(secret, beacon, i, namespace=namespace)\n        visible.append(v)\n        hidden.append(h)\n    for i in range(PRODUCTION_CASE_COUNTS[ABSTAIN]):\n        v, h = _abstention_case(secret, beacon, i, namespace=namespace)\n        visible.append(v)\n        hidden.append(h)\n    ids = [x[\"case_id\"] for x in visible]\n    if len(ids) != 27 or len(ids) != len(set(ids)):\n        raise UnknownDomainGeneratorError(\"CASE_ID_SET_INVALID\")\n    return {\n        \"schema\": SCHEMA,\n        \"case_count\": 27,\n        \"visible_cases\": visible,\n        \"hidden_records\": hidden,\n        \"visible_packet_digest\": _sha256(visible),\n        \"hidden_packet_digest\": _sha256(hidden),\n    }\n\n\ndef generate_production_population(\n    *,\n    beacon: str,\n    evaluator_secret: Any,\n    authority: Mapping[str, Any],\n) -> dict[str, Any]:\n    _production_authorized(authority)\n    out = _generate(beacon=beacon, evaluator_secret=evaluator_secret, namespace=\"UDIR\")\n    out[\"authority_claim_id\"] = str(authority[\"one_use_claim_id\"])\n    out[\"production\"] = True\n    return out\n\n\ndef generate_test_fixture_population() -> dict[str, Any]:\n    out = _generate(\n        beacon=\"TEST-ONLY-BEACON-DOES-NOT-AUTHORIZE-REALITY\",\n        evaluator_secret=b\"TEST-ONLY-SECRET-0123456789-ABCDEFGHIJK\",\n        namespace=\"TESTONLY\",\n    )\n    out[\"production\"] = False\n    out[\"hard_nonclaim\"] = \"TEST_FIXTURES_ARE_NOT_PRODUCTION_OR_TERMINAL_CASES\"\n    return out\n","canonical/runtime/unknown_domain_direct_hidden_generator_v2.py":"\"\"\"Unknown-Domain direct hidden generator V2.\n\nV2 preserves the independently verified V1 authority and packet schemas while\nmaking all task-level numeric parameters and observations depend on the unseen\npost-freeze beacon plus evaluator-only secret. This prevents candidate\nqualification from overfitting the public TEST_ONLY fixture's numeric values.\n\nNo production case is generated on import or verification. Production generation\nstill requires the exact V1 predicate-local one-use authority gate.\n\"\"\"\nfrom __future__ import annotations\n\nimport hmac\nimport hashlib\nfrom typing import Any, Mapping\n\nfrom canonical.runtime import unknown_domain_direct_hidden_generator_v1 as v1\n\nSCHEMA=\"PROJECT_BRAIN_UNKNOWN_DOMAIN_DIRECT_HIDDEN_GENERATOR_V2\"\n\n\ndef _unit(secret:bytes, beacon:str, *parts:Any)->float:\n    msg=\"|\".join([beacon]+[str(x) for x in parts]).encode()\n    raw=hmac.new(secret,msg,hashlib.sha256).digest()[:8]\n    return int.from_bytes(raw,\"big\") / float((1<<64)-1)\n\n\ndef _range(secret:bytes, beacon:str, lo:float, hi:float, *parts:Any)->float:\n    return lo + (hi-lo)*_unit(secret,beacon,*parts)\n\n\ndef _program_for(secret:bytes, beacon:str, index:int):\n    family=v1.PRIMITIVE_FAMILIES[index % len(v1.PRIMITIVE_FAMILIES)]\n    if family==\"ORDER_PRESERVING_TRANSFORM\":\n        program={\"dsl\":\"UDIR_V1\",\"op\":\"AFFINE_POS\",\"roles\":[\"r0\"],\"params\":{\n            \"bias\":_range(secret,beacon,-2.0,2.0,\"param\",index,\"bias\"),\n            \"gain\":_range(secret,beacon,0.6,2.6,\"param\",index,\"gain\"),\n        }}\n    elif family==\"PARITY_OR_SIGN_INVARIANT\":\n        program={\"dsl\":\"UDIR_V1\",\"op\":\"SIGN\",\"roles\":[\"r0\"],\"params\":{}}\n    elif family==\"CONSERVATION_RELATION\":\n        program={\"dsl\":\"UDIR_V1\",\"op\":\"COMPLEMENT\",\"roles\":[\"r0\"],\"params\":{\n            \"total\":_range(secret,beacon,2.0,8.0,\"param\",index,\"total\"),\n        }}\n    elif family==\"MONOTONE_CAUSAL_EDGE\":\n        program={\"dsl\":\"UDIR_V1\",\"op\":\"SAT_MONO\",\"roles\":[\"r0\"],\"params\":{\n            \"bias\":_range(secret,beacon,-1.5,1.5,\"param\",index,\"bias\"),\n            \"gain\":_range(secret,beacon,0.7,3.0,\"param\",index,\"gain\"),\n        }}\n    elif family==\"COMPOSITIONAL_REWRITE\":\n        program={\"dsl\":\"UDIR_V1\",\"op\":\"ADD2\",\"roles\":[\"r0\",\"r1\"],\"params\":{\n            \"bias\":_range(secret,beacon,-2.0,2.0,\"param\",index,\"bias\"),\n        }}\n    else:\n        threshold=_range(secret,beacon,-1.25,1.25,\"param\",index,\"threshold\")\n        low=_range(secret,beacon,-2.5,-0.5,\"param\",index,\"low\")\n        high=_range(secret,beacon,0.5,2.5,\"param\",index,\"high\")\n        program={\"dsl\":\"UDIR_V1\",\"op\":\"STEP\",\"roles\":[\"r0\"],\"params\":{\n            \"threshold\":threshold,\"low\":low,\"high\":high,\n        }}\n    return family,program,list(program[\"roles\"])\n\n\ndef _role_rows(secret:bytes, beacon:str, index:int, program:Mapping[str,Any], *, domain:str):\n    op=str(program[\"op\"])\n    rows=[]\n    if op==\"STEP\":\n        t=float(program[\"params\"][\"threshold\"])\n        for j in range(6):\n            mag=_range(secret,beacon,0.35,2.2,\"row\",index,domain,j,\"mag\")\n            sign=-1.0 if j%2==0 else 1.0\n            rows.append({\"r0\":t+sign*mag})\n        return rows\n\n    for j in range(6):\n        mag0=_range(secret,beacon,0.25,3.5,\"row\",index,domain,j,\"r0\")\n        sign0=-1.0 if (j+index)%2==0 else 1.0\n        row={\"r0\":sign0*mag0}\n        if \"r1\" in program[\"roles\"]:\n            mag1=_range(secret,beacon,0.25,3.5,\"row\",index,domain,j,\"r1\")\n            sign1=-1.0 if (j+index+1)%3==0 else 1.0\n            row[\"r1\"]=sign1*mag1\n        rows.append(row)\n    return rows\n\n\ndef _transfer_case(secret:bytes, beacon:str, index:int, *, namespace:str):\n    family,program,roles=_program_for(secret,beacon,index)\n    fingerprint=v1._sha256(program)\n    source_rows=_role_rows(secret,beacon,index,program,domain=\"A\")\n    target_rows=_role_rows(secret,beacon,index,program,domain=\"B\")\n    a_map,a_distractors=v1._surface_ids(secret,beacon,index,namespace+\"_A\",roles)\n    b_map,b_distractors=v1._surface_ids(secret,beacon,index,namespace+\"_B\",roles)\n    if (set(a_map.values())|set(a_distractors)) & (set(b_map.values())|set(b_distractors)):\n        raise v1.UnknownDomainGeneratorError(\"DOMAIN_VOCABULARY_OVERLAP\")\n\n    source_observations=[]\n    for j,row in enumerate(source_rows[:3]):\n        source_observations.append({\n            \"inputs\":v1._surface_row(row,a_map,a_distractors,mimic_visible=False,probe_variant=j),\n            \"terminal_consequence\":v1._eval(program,row),\n        })\n\n    target_observations=[]\n    for j,row in enumerate(target_rows[:3]):\n        target_observations.append({\n            \"inputs\":v1._surface_row(row,b_map,b_distractors,mimic_visible=True,probe_variant=j),\n            \"terminal_consequence\":v1._eval(program,row),\n        })\n\n    receipt_id=f\"R-{v1._token(secret,beacon,'receipt',index,namespace)}\"\n    receipt={\n        \"receipt_id\":receipt_id,\n        \"normalized_primitive_program\":program,\n        \"primitive_fingerprint\":fingerprint,\n        \"source_role_binding\":dict(a_map),\n        \"source_evidence_digest\":v1._sha256(source_observations),\n        \"independent_verified\":True,\n        \"exact_byte_bound\":True,\n        \"conclusion\":\"success\",\n    }\n\n    probes=[]\n    probe_hidden={}\n    for j,row in enumerate(target_rows[3:5]):\n        pid=f\"P-{v1._token(secret,beacon,'probe',index,j,namespace)}\"\n        probes.append({\n            \"probe_id\":pid,\n            \"argument_schema\":{\"type\":\"OBSERVE_PRECOMMITTED_ROW\",\"row_slot\":j},\n            \"cost\":j+1,\n        })\n        probe_hidden[pid]={\n            \"inputs\":v1._surface_row(row,b_map,b_distractors,mimic_visible=False,probe_variant=j),\n            \"terminal_consequence\":v1._eval(program,row),\n        }\n\n    query_roles=target_rows[5]\n    query_inputs=v1._surface_row(query_roles,b_map,b_distractors,mimic_visible=False,probe_variant=9)\n    case_id=f\"{namespace}-T-{v1._token(secret,beacon,'case',v1.TRANSFER,index,namespace,width=20)}\"\n    visible={\n        \"case_id\":case_id,\n        \"leaf_id\":v1.TRANSFER,\n        \"domain_a\":{\"tasks\":source_observations,\"earned_receipts\":[receipt]},\n        \"domain_b\":{\n            \"tasks\":target_observations,\n            \"query_inputs\":query_inputs,\n            \"allowed_probes\":probes,\n            \"tool_metadata\":{\n                \"input_shape\":\"OPAQUE_FEATURE_VALUE_MAP\",\n                \"output_shape\":\"SCALAR_TERMINAL_CONSEQUENCE\",\n            },\n        },\n        \"decision_requirement\":\"PREDICT_TERMINAL_CONSEQUENCE_AND_PROVIDE_TRANSFER_PROOF_TRACE\",\n    }\n    relevant=[b_map[r] for r in roles]\n    hidden={\n        \"case_id\":case_id,\n        \"leaf_id\":v1.TRANSFER,\n        \"primitive_family\":family,\n        \"latent_primitive_program\":program,\n        \"latent_primitive_fingerprint\":fingerprint,\n        \"domain_mapping\":dict(b_map),\n        \"domain_a_earned_receipt_ids\":[receipt_id],\n        \"domain_a_receipt_primitive_bindings\":{receipt_id:fingerprint},\n        \"transfer_relevant_feature_ids\":relevant,\n        \"distractor_feature_ids\":list(b_distractors),\n        \"gold_terminal_consequence\":v1._eval(program,query_roles),\n        \"full_rediscovery_probe_floor\":3,\n        \"surface_label_permutation_verified\":True,\n        \"domain_vocabularies_disjoint\":True,\n        \"allowed_probe_outcome_table\":probe_hidden,\n    }\n    return visible,hidden\n\n\ndef _generate(*, beacon:str, evaluator_secret:Any, namespace:str):\n    if not isinstance(beacon,str) or len(beacon.strip())<16:\n        raise v1.UnknownDomainGeneratorError(\"POST_FREEZE_BEACON_INVALID\")\n    secret=v1._secret_bytes(evaluator_secret)\n    visible=[]\n    hidden=[]\n    for i in range(v1.PRODUCTION_CASE_COUNTS[v1.TRANSFER]):\n        a,b=_transfer_case(secret,beacon,i,namespace=namespace)\n        visible.append(a); hidden.append(b)\n    for i in range(v1.PRODUCTION_CASE_COUNTS[v1.ABSTAIN]):\n        a,b=v1._abstention_case(secret,beacon,i,namespace=namespace)\n        visible.append(a); hidden.append(b)\n    ids=[x[\"case_id\"] for x in visible]\n    if len(ids)!=27 or len(ids)!=len(set(ids)):\n        raise v1.UnknownDomainGeneratorError(\"CASE_ID_SET_INVALID\")\n    return {\n        \"schema\":SCHEMA,\n        \"case_count\":27,\n        \"visible_cases\":visible,\n        \"hidden_records\":hidden,\n        \"visible_packet_digest\":v1._sha256(visible),\n        \"hidden_packet_digest\":v1._sha256(hidden),\n    }\n\n\ndef generate_production_population(*, beacon:str, evaluator_secret:Any, authority:Mapping[str,Any]):\n    v1._production_authorized(authority)\n    out=_generate(beacon=beacon,evaluator_secret=evaluator_secret,namespace=\"UDIR\")\n    out[\"authority_claim_id\"]=str(authority[\"one_use_claim_id\"])\n    out[\"production\"]=True\n    return out\n\n\ndef generate_qualification_fixture_population(*, beacon:str):\n    if not isinstance(beacon,str) or len(beacon.strip())<16:\n        raise v1.UnknownDomainGeneratorError(\"QUALIFICATION_BEACON_INVALID\")\n    out=_generate(\n        beacon=\"QUALIFICATION-ONLY|\"+beacon,\n        evaluator_secret=b\"QUALIFICATION-ONLY-SECRET-0123456789-ABCDEFG\",\n        namespace=\"QUALONLY\",\n    )\n    out[\"production\"]=False\n    out[\"hard_nonclaim\"]=\"QUALIFICATION_FIXTURES_ARE_NOT_PRODUCTION_OR_TERMINAL_CASES\"\n    return out\n","canonical/runtime/unknown_domain_direct_hidden_scorer_v1.py":"\"\"\"Deterministic hidden scorer for the two frozen Unknown-Domain direct leaves.\n\nThe scorer receives hidden evaluator truth plus a candidate trace. Candidate\nself-reported pass/verified flags are ignored. It grants no acceptance credit;\nit only returns exact leaf-level case verdicts for later independent reduction.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any, Mapping, Sequence\n\nSCHEMA=\"PROJECT_BRAIN_UNKNOWN_DOMAIN_DIRECT_HIDDEN_SCORER_V1\"\nTRANSFER=\"CROSS_DOMAIN_TRANSFER_OUTSIDE_MYSTERYMECHANISM_TASK_STRUCTURE\"\nABSTAIN=\"CALIBRATED_UNKNOWN_OR_ABSTENTION_ON_NONIDENTIFIABLE_OR_UNDERSPECIFIED_VARIANTS\"\nDECISIONS={\"CONCLUDE\",\"ABSTAIN\",\"REQUEST_DISCRIMINATOR\"}\n\n\nclass UnknownDomainScorerError(ValueError):\n    pass\n\n\ndef _strings(value: Any, field: str, *, nonempty: bool=False) -> list[str]:\n    if not isinstance(value, Sequence) or isinstance(value,(str,bytes)):\n        raise UnknownDomainScorerError(field+\"_INVALID\")\n    rows=[str(x).strip() for x in value]\n    if any(not x for x in rows):\n        raise UnknownDomainScorerError(field+\"_EMPTY_ITEM\")\n    if nonempty and not rows:\n        raise UnknownDomainScorerError(field+\"_EMPTY\")\n    if len(rows)!=len(set(rows)):\n        raise UnknownDomainScorerError(field+\"_DUPLICATE\")\n    return rows\n\n\ndef _provenance_ok(rows: Any, required_evidence: set[str]) -> tuple[bool,list[str]]:\n    errors=[]\n    if not isinstance(rows,Sequence) or isinstance(rows,(str,bytes)):\n        return False,[\"PROVENANCE_NOT_LIST\"]\n    seen=set()\n    for i,row in enumerate(rows):\n        if not isinstance(row,Mapping):\n            errors.append(f\"PROVENANCE_NOT_OBJECT:{i}\")\n            continue\n        eid=str(row.get(\"evidence_id\") or \"\").strip()\n        src=str(row.get(\"source\") or \"\").strip()\n        receipt=str(row.get(\"receipt\") or \"\").strip()\n        if not eid or not src or not receipt:\n            errors.append(f\"PROVENANCE_INCOMPLETE:{i}\")\n            continue\n        seen.add(eid)\n    missing=sorted(required_evidence-seen)\n    errors.extend(\"PROVENANCE_MISSING:\"+x for x in missing)\n    return not errors,errors\n\n\ndef score_transfer(hidden: Mapping[str,Any], trace: Mapping[str,Any]) -> dict[str,Any]:\n    errors=[]\n    if hidden.get(\"leaf_id\")!=TRANSFER:\n        raise UnknownDomainScorerError(\"TRANSFER_LEAF_ID_INVALID\")\n    if trace.get(\"decision\")!=\"CONCLUDE\":\n        errors.append(\"DOMAIN_B_DID_NOT_CONCLUDE\")\n    if trace.get(\"terminal_consequence\")!=hidden.get(\"gold_terminal_consequence\"):\n        errors.append(\"DOMAIN_B_TERMINAL_CONSEQUENCE_WRONG\")\n\n    allowed_receipts=set(_strings(hidden.get(\"domain_a_earned_receipt_ids\"),\"HIDDEN_DOMAIN_A_RECEIPTS\",nonempty=True))\n    used_receipts=set(_strings(trace.get(\"domain_a_source_receipt_ids\",[]),\"TRACE_DOMAIN_A_RECEIPTS\"))\n    load_bearing=allowed_receipts & used_receipts\n    if not load_bearing:\n        errors.append(\"NO_DOMAIN_A_EARNED_RECEIPT_REUSED\")\n\n    primitive=str(hidden.get(\"latent_primitive_fingerprint\") or \"\").strip()\n    bindings=hidden.get(\"domain_a_receipt_primitive_bindings\")\n    if not primitive or not isinstance(bindings,Mapping):\n        raise UnknownDomainScorerError(\"HIDDEN_PRIMITIVE_BINDING_INVALID\")\n    bound_receipts={str(rid) for rid,value in bindings.items() if str(value)==primitive}\n    if not (load_bearing & bound_receipts):\n        errors.append(\"REUSED_RECEIPT_NOT_BOUND_TO_SHARED_PRIMITIVE\")\n    if str(trace.get(\"transferred_primitive_fingerprint\") or \"\").strip()!=primitive:\n        errors.append(\"TRANSFERRED_PRIMITIVE_FINGERPRINT_MISMATCH\")\n    if hidden.get(\"surface_label_permutation_verified\") is not True:\n        raise UnknownDomainScorerError(\"HIDDEN_SURFACE_PERMUTATION_NOT_VERIFIED\")\n    if hidden.get(\"domain_vocabularies_disjoint\") is not True:\n        raise UnknownDomainScorerError(\"HIDDEN_DOMAIN_VOCABULARIES_NOT_DISJOINT\")\n\n    probe_count=trace.get(\"domain_b_discovery_probe_count\")\n    floor=hidden.get(\"full_rediscovery_probe_floor\")\n    if isinstance(probe_count,bool) or not isinstance(probe_count,int) or probe_count<0:\n        errors.append(\"DOMAIN_B_PROBE_COUNT_INVALID\")\n    if isinstance(floor,bool) or not isinstance(floor,int) or floor<=0:\n        raise UnknownDomainScorerError(\"HIDDEN_REDISCOVERY_FLOOR_INVALID\")\n    if isinstance(probe_count,int) and not isinstance(probe_count,bool) and probe_count>=floor:\n        errors.append(\"FULL_REDISCOVERY_NOT_AVOIDED\")\n\n    relevant=set(_strings(hidden.get(\"transfer_relevant_feature_ids\"),\"HIDDEN_RELEVANT\",nonempty=True))\n    distractors=set(_strings(hidden.get(\"distractor_feature_ids\"),\"HIDDEN_DISTRACTORS\",nonempty=True))\n    if relevant & distractors:\n        raise UnknownDomainScorerError(\"HIDDEN_RELEVANT_DISTRACTOR_OVERLAP\")\n    support=set(_strings(trace.get(\"support_feature_ids\",[]),\"TRACE_SUPPORT_FEATURES\"))\n    rejected=set(_strings(trace.get(\"negative_transfer_rejected_feature_ids\",[]),\"TRACE_REJECTED_FEATURES\"))\n    if support!=relevant:\n        errors.append(\"TRANSFER_SUPPORT_DOES_NOT_MATCH_HIDDEN_RELEVANT_SET\")\n    if support & distractors:\n        errors.append(\"DISTRACTOR_USED_AS_POSITIVE_SUPPORT\")\n    if not distractors.issubset(rejected):\n        errors.append(\"NEGATIVE_TRANSFER_DISTRACTORS_NOT_ALL_REJECTED\")\n\n    mapping=str(trace.get(\"mapping_basis\") or \"\").strip()\n    admissible_mapping=mapping in {\"STRUCTURAL_EQUIVALENCE\",\"CAUSAL_ISOMORPHISM\",\"FORMAL_REDUCTION\",\"PROTOCOL_EQUIVALENCE\"}\n    if not admissible_mapping:\n        errors.append(\"TRANSFER_MAPPING_BASIS_NOT_ADMISSIBLE\")\n\n    required_evidence=set(load_bearing)|support|distractors\n    _,prov_errors=_provenance_ok(trace.get(\"evidence_provenance\"),required_evidence)\n    errors.extend(prov_errors)\n\n    passed=not errors\n    return {\n        \"schema\":SCHEMA,\n        \"leaf_id\":TRANSFER,\n        \"case_id\":hidden.get(\"case_id\"),\n        \"pass\":passed,\n        \"errors\":sorted(set(errors)),\n        \"acceptance_clauses\":{\n            \"domain_b_terminal_success\":\"PASS\" if not ({\"DOMAIN_B_TERMINAL_CONSEQUENCE_WRONG\",\"DOMAIN_B_DID_NOT_CONCLUDE\"} & set(errors)) else \"FAIL\",\n            \"reuses_domain_a_without_full_rediscovery\":\"PASS\" if not ({\"NO_DOMAIN_A_EARNED_RECEIPT_REUSED\",\"REUSED_RECEIPT_NOT_BOUND_TO_SHARED_PRIMITIVE\",\"TRANSFERRED_PRIMITIVE_FINGERPRINT_MISMATCH\",\"FULL_REDISCOVERY_NOT_AVOIDED\"} & set(errors)) else \"FAIL\",\n            \"not_label_or_identifier_memorization\":\"PASS\" if support==relevant and admissible_mapping and hidden.get(\"surface_label_permutation_verified\") is True and hidden.get(\"domain_vocabularies_disjoint\") is True else \"FAIL\",\n            \"negative_transfer_distractors_rejected\":\"PASS\" if not (support & distractors) and distractors.issubset(rejected) else \"FAIL\",\n            \"evidence_provenance_preserved\":\"PASS\" if not prov_errors else \"FAIL\"\n        },\n        \"acceptance_credit_delta\":0,\n        \"family_credit_delta\":0,\n        \"promotion_authority\":False\n    }\n\n\ndef score_abstention(hidden: Mapping[str,Any], trace: Mapping[str,Any]) -> dict[str,Any]:\n    errors=[]\n    if hidden.get(\"leaf_id\")!=ABSTAIN:\n        raise UnknownDomainScorerError(\"ABSTENTION_LEAF_ID_INVALID\")\n    status=str(hidden.get(\"identifiability_status\") or \"\")\n    if status not in {\"IDENTIFIABLE\",\"NONIDENTIFIABLE\",\"UNDERSPECIFIED\"}:\n        raise UnknownDomainScorerError(\"HIDDEN_IDENTIFIABILITY_STATUS_INVALID\")\n    decision=str(trace.get(\"decision\") or \"\")\n    if decision not in DECISIONS:\n        errors.append(\"DECISION_INVALID\")\n    witness=str(trace.get(\"nonidentifiability_witness\") or \"\").strip()\n\n    if status==\"IDENTIFIABLE\":\n        if decision!=\"CONCLUDE\":\n            errors.append(\"IDENTIFIABLE_CASE_NOT_CONCLUDED\")\n        if trace.get(\"terminal_consequence\")!=hidden.get(\"gold_terminal_consequence\"):\n            errors.append(\"IDENTIFIABLE_CONCLUSION_WRONG\")\n    elif status==\"NONIDENTIFIABLE\":\n        if decision!=\"ABSTAIN\":\n            errors.append(\"NONIDENTIFIABLE_CASE_FORCED_OR_WRONG_DECISION\")\n        if not witness:\n            errors.append(\"NONIDENTIFIABILITY_WITNESS_MISSING\")\n    else:\n        minimum=str(hidden.get(\"minimum_discriminator_id\") or \"\").strip()\n        if not minimum:\n            raise UnknownDomainScorerError(\"HIDDEN_MINIMUM_DISCRIMINATOR_MISSING\")\n        if decision==\"REQUEST_DISCRIMINATOR\":\n            if str(trace.get(\"discriminator\") or \"\").strip()!=minimum:\n                errors.append(\"WRONG_DISCRIMINATOR_REQUESTED\")\n        elif decision==\"ABSTAIN\":\n            if not witness:\n                errors.append(\"UNDERSPECIFIED_ABSTENTION_WITNESS_MISSING\")\n        else:\n            errors.append(\"UNDERSPECIFIED_CASE_FORCED_CONCLUSION\")\n\n    passed=not errors\n    return {\n        \"schema\":SCHEMA,\n        \"leaf_id\":ABSTAIN,\n        \"case_id\":hidden.get(\"case_id\"),\n        \"case_class\":status,\n        \"pass\":passed,\n        \"errors\":sorted(set(errors)),\n        \"acceptance_clauses\":{\n            \"identifiable_correct_supported_conclusion\":\"PASS\" if status!=\"IDENTIFIABLE\" or passed else \"FAIL\",\n            \"nonidentifiable_no_forced_unique_conclusion\":\"PASS\" if status!=\"NONIDENTIFIABLE\" or passed else \"FAIL\",\n            \"underspecified_valid_discriminator_or_abstain\":\"PASS\" if status!=\"UNDERSPECIFIED\" or passed else \"FAIL\",\n            \"no_blanket_abstention_on_identifiable\":\"PASS\" if status!=\"IDENTIFIABLE\" or decision==\"CONCLUDE\" else \"FAIL\"\n        },\n        \"acceptance_credit_delta\":0,\n        \"family_credit_delta\":0,\n        \"promotion_authority\":False\n    }\n\n\ndef score_case(hidden: Mapping[str,Any], trace: Mapping[str,Any]) -> dict[str,Any]:\n    leaf=hidden.get(\"leaf_id\")\n    if leaf==TRANSFER:\n        return score_transfer(hidden,trace)\n    if leaf==ABSTAIN:\n        return score_abstention(hidden,trace)\n    raise UnknownDomainScorerError(\"LEAF_ID_UNKNOWN\")\n\n\ndef aggregate(results: Sequence[Mapping[str,Any]]) -> dict[str,Any]:\n    if not isinstance(results,Sequence) or isinstance(results,(str,bytes)) or not results:\n        raise UnknownDomainScorerError(\"RESULTS_REQUIRED\")\n    transfer=[r for r in results if r.get(\"leaf_id\")==TRANSFER]\n    abstain=[r for r in results if r.get(\"leaf_id\")==ABSTAIN]\n    if len(transfer)!=12 or len(abstain)!=15:\n        raise UnknownDomainScorerError(\"FROZEN_CASE_COUNT_MISMATCH\")\n    ids=[str(r.get(\"case_id\") or \"\") for r in results]\n    if any(not x for x in ids) or len(ids)!=len(set(ids)):\n        raise UnknownDomainScorerError(\"CASE_IDS_INVALID_OR_DUPLICATE\")\n    classes={\"IDENTIFIABLE\":0,\"NONIDENTIFIABLE\":0,\"UNDERSPECIFIED\":0}\n    for row in abstain:\n        cls=str(row.get(\"case_class\") or \"\")\n        if cls not in classes:\n            raise UnknownDomainScorerError(\"ABSTENTION_CASE_CLASS_INVALID\")\n        classes[cls]+=1\n    if classes!={\"IDENTIFIABLE\":5,\"NONIDENTIFIABLE\":5,\"UNDERSPECIFIED\":5}:\n        raise UnknownDomainScorerError(\"ABSTENTION_CLASS_BALANCE_MISMATCH\")\n    transfer_pass=all(r.get(\"pass\") is True for r in transfer)\n    abstention_pass=all(r.get(\"pass\") is True for r in abstain)\n    return {\n        \"schema\":SCHEMA,\n        \"status\":\"TWO_FROZEN_LEAVES_PASS\" if transfer_pass and abstention_pass else \"DIRECT_LEAF_RESIDUAL_REMAINS\",\n        \"transfer_leaf_pass\":transfer_pass,\n        \"abstention_leaf_pass\":abstention_pass,\n        \"all_27_cases_pass\":transfer_pass and abstention_pass,\n        \"case_count\":27,\n        \"class_balance\":classes,\n        \"acceptance_credit_delta\":0,\n        \"family_credit_delta\":0,\n        \"promotion_authority\":False,\n        \"separate_independent_reduction_required\":True\n    }\n","canonical/runtime/unknown_domain_direct_execution_harness_v1.py":"\"\"\"Frozen interaction harness for Unknown-Domain direct evaluation V1.\n\nThe candidate receives only (case_visible, transcript). Hidden evaluator truth is\nheld by the harness and passed only to the frozen hidden scorer after a terminal\ncandidate action. Probe results enter the transcript only after the candidate\nrequests an allowed probe.\n\nThis module does not generate production cases and grants no execution authority.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any, Callable, Mapping, Sequence\n\nfrom canonical.runtime import unknown_domain_direct_hidden_scorer_v1 as scorer\n\nSCHEMA=\"PROJECT_BRAIN_UNKNOWN_DOMAIN_DIRECT_EXECUTION_HARNESS_V1\"\nTERMINAL_TYPES={\"CONCLUDE\",\"ABSTAIN\",\"REQUEST_DISCRIMINATOR\"}\nMAX_TRANSFER_PROBES=2\nMAX_STEPS=4\n\n\nclass UnknownDomainHarnessError(ValueError):\n    pass\n\n\ndef _allowed_probes(case_visible: Mapping[str,Any]) -> dict[str,Mapping[str,Any]]:\n    leaf=case_visible.get(\"leaf_id\")\n    if leaf==scorer.TRANSFER:\n        rows=case_visible.get(\"domain_b\",{}).get(\"allowed_probes\",[])\n    elif leaf==scorer.ABSTAIN:\n        rows=case_visible.get(\"allowed_probes\",[])\n    else:\n        raise UnknownDomainHarnessError(\"LEAF_ID_UNKNOWN\")\n    if not isinstance(rows,Sequence) or isinstance(rows,(str,bytes)):\n        raise UnknownDomainHarnessError(\"ALLOWED_PROBES_INVALID\")\n    out={}\n    for row in rows:\n        if not isinstance(row,Mapping):\n            raise UnknownDomainHarnessError(\"ALLOWED_PROBE_NOT_OBJECT\")\n        pid=str(row.get(\"probe_id\") or \"\").strip()\n        if not pid or pid in out:\n            raise UnknownDomainHarnessError(\"ALLOWED_PROBE_ID_INVALID_OR_DUPLICATE\")\n        out[pid]=row\n    return out\n\n\ndef _terminal_trace(action: Mapping[str,Any], *, probe_count:int) -> dict[str,Any]:\n    kind=str(action.get(\"type\") or \"\").strip()\n    if kind not in TERMINAL_TYPES:\n        raise UnknownDomainHarnessError(\"TERMINAL_ACTION_TYPE_INVALID\")\n    trace={k:v for k,v in action.items() if k!=\"type\"}\n    trace[\"decision\"]=kind\n    trace[\"domain_b_discovery_probe_count\"]=probe_count\n    return trace\n\n\ndef execute_case(\n    *,\n    candidate_step: Callable[[Mapping[str,Any], Sequence[Mapping[str,Any]]], Mapping[str,Any]],\n    case_visible: Mapping[str,Any],\n    hidden_record: Mapping[str,Any],\n) -> dict[str,Any]:\n    if not callable(candidate_step):\n        raise UnknownDomainHarnessError(\"CANDIDATE_STEP_NOT_CALLABLE\")\n    if not isinstance(case_visible,Mapping) or not isinstance(hidden_record,Mapping):\n        raise UnknownDomainHarnessError(\"CASE_PACKET_INVALID\")\n    if case_visible.get(\"case_id\")!=hidden_record.get(\"case_id\"):\n        raise UnknownDomainHarnessError(\"CASE_ID_MISMATCH\")\n    if case_visible.get(\"leaf_id\")!=hidden_record.get(\"leaf_id\"):\n        raise UnknownDomainHarnessError(\"LEAF_ID_MISMATCH\")\n\n    allowed=_allowed_probes(case_visible)\n    hidden_table=hidden_record.get(\"allowed_probe_outcome_table\",{})\n    if not isinstance(hidden_table,Mapping):\n        raise UnknownDomainHarnessError(\"HIDDEN_PROBE_TABLE_INVALID\")\n\n    transcript=[]\n    requested=set()\n    for step_index in range(MAX_STEPS):\n        # Fresh containers prevent accidental mutation of harness-owned packets.\n        visible_view=dict(case_visible)\n        transcript_view=tuple(dict(x) for x in transcript)\n        action=candidate_step(visible_view,transcript_view)\n        if not isinstance(action,Mapping):\n            raise UnknownDomainHarnessError(\"CANDIDATE_ACTION_NOT_OBJECT\")\n        kind=str(action.get(\"type\") or \"\").strip()\n\n        if kind==\"REQUEST_PROBE\":\n            if case_visible.get(\"leaf_id\")!=scorer.TRANSFER:\n                raise UnknownDomainHarnessError(\"REQUEST_PROBE_ONLY_ALLOWED_FOR_TRANSFER\")\n            pid=str(action.get(\"probe_id\") or \"\").strip()\n            if pid not in allowed:\n                raise UnknownDomainHarnessError(\"REQUESTED_PROBE_NOT_ALLOWED\")\n            if pid in requested:\n                raise UnknownDomainHarnessError(\"REQUESTED_PROBE_DUPLICATE\")\n            if len(requested)>=MAX_TRANSFER_PROBES:\n                raise UnknownDomainHarnessError(\"TRANSFER_PROBE_BUDGET_EXCEEDED\")\n            if pid not in hidden_table:\n                raise UnknownDomainHarnessError(\"HIDDEN_PROBE_RESULT_MISSING\")\n            requested.add(pid)\n            transcript.append({\n                \"step\":step_index,\n                \"requested_probe_id\":pid,\n                \"probe_result\":hidden_table[pid],\n            })\n            continue\n\n        if kind in TERMINAL_TYPES:\n            trace=_terminal_trace(action,probe_count=len(requested))\n            result=scorer.score_case(hidden_record,trace)\n            return {\n                \"schema\":SCHEMA,\n                \"case_id\":case_visible.get(\"case_id\"),\n                \"leaf_id\":case_visible.get(\"leaf_id\"),\n                \"candidate_terminal_action\":dict(action),\n                \"transcript\":transcript,\n                \"probe_count\":len(requested),\n                \"scorer_result\":result,\n                \"acceptance_credit_delta\":0,\n                \"family_credit_delta\":0,\n                \"promotion_authority\":False,\n            }\n\n        raise UnknownDomainHarnessError(\"CANDIDATE_ACTION_TYPE_INVALID\")\n\n    raise UnknownDomainHarnessError(\"MAX_STEPS_EXCEEDED\")\n","canonical/runtime/unknown_domain_direct_v2_universal_proof_v1.py":"\"\"\"Content-bound universal proof for the frozen Unknown-Domain direct V2 route.\n\nThis module proves the exact V2 candidate succeeds for every population emitted\nby the exact frozen V2 generator, for every valid post-freeze beacon and\nevaluator secret.  It consumes no production case and does not grant acceptance\ncredit by itself.  The theorem is valid only for the exact Git blobs bound below.\n\nThe proof is structural:\n* injective unary primitives reject shifted distractors;\n* SIGN always receives one negative transfer probe while every distractor is\n  forced positive;\n* STEP always receives one below-threshold probe while every distractor is\n  forced above threshold;\n* ADD2's first transfer probe has both true roles positive, giving every\n  wrong-support pair a strictly positive score gap;\n* the three abstention classes are decided directly from their visible contract.\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nfrom pathlib import Path\nfrom typing import Any\n\nfrom canonical.runtime import unknown_domain_direct_hidden_generator_v1 as g1\nfrom canonical.runtime import unknown_domain_direct_hidden_generator_v2 as g2\nfrom canonical.runtime import unknown_domain_direct_hidden_scorer_v1 as scorer\nfrom canonical.runtime import unknown_domain_direct_execution_harness_v1 as harness\nfrom canonical.runtime import unknown_domain_direct_candidate_v1 as c1\nfrom canonical.runtime import unknown_domain_direct_candidate_v2 as c2\n\nSCHEMA = \"PROJECT_BRAIN_UNKNOWN_DOMAIN_DIRECT_V2_UNIVERSAL_PROOF_V1\"\n\nEXPECTED_BLOBS = {\n    \"canonical/runtime/unknown_domain_direct_candidate_v1.py\":\n        \"a2a77269a8175ce315b466035049da0f761b8734\",\n    \"canonical/runtime/unknown_domain_direct_candidate_v2.py\":\n        \"4470716f95a559a700e461262df909ae19a41651\",\n    \"canonical/runtime/unknown_domain_direct_hidden_generator_v1.py\":\n        \"f974a4594c78e74693c7ba5a19f131dfa481b937\",\n    \"canonical/runtime/unknown_domain_direct_hidden_generator_v2.py\":\n        \"d077028c9bde534dc4bc6eb0d1f776341f9d59f8\",\n    \"canonical/runtime/unknown_domain_direct_hidden_scorer_v1.py\":\n        \"e8cf5d1b5d311644725a751c15e6235958fb587d\",\n    \"canonical/runtime/unknown_domain_direct_execution_harness_v1.py\":\n        \"04fe06f4eed081c4cb6197b12f2d92bd396aeafd\",\n}\n\nFAMILIES = (\n    \"ORDER_PRESERVING_TRANSFORM\",\n    \"PARITY_OR_SIGN_INVARIANT\",\n    \"CONSERVATION_RELATION\",\n    \"MONOTONE_CAUSAL_EDGE\",\n    \"COMPOSITIONAL_REWRITE\",\n    \"THRESHOLD_OR_PARTITION_INVARIANT\",\n)\n\n\ndef _git_blob_sha(path: Path) -> str:\n    data = path.read_bytes()\n    return hashlib.sha1(b\"blob \" + str(len(data)).encode() + b\"\\0\" + data).hexdigest()\n\n\ndef _repo_root() -> Path:\n    return Path(__file__).resolve().parents[2]\n\n\ndef _verify_bindings(root: Path) -> dict[str, str]:\n    got = {rel: _git_blob_sha(root / rel) for rel in EXPECTED_BLOBS}\n    bad = {rel: {\"expected\": EXPECTED_BLOBS[rel], \"got\": got[rel]}\n           for rel in EXPECTED_BLOBS if got[rel] != EXPECTED_BLOBS[rel]}\n    if bad:\n        raise AssertionError(\"EXACT_SUBJECT_BLOB_MISMATCH:\" + repr(bad))\n    return got\n\n\ndef _transfer_theorem() -> dict[str, Any]:\n    # Frozen generator invariants.\n    assert tuple(g1.PRIMITIVE_FAMILIES) == FAMILIES\n    assert g1.PRODUCTION_CASE_COUNTS[g1.TRANSFER] == 12\n    assert harness.MAX_TRANSFER_PROBES == 2\n    assert c1.MAPPING_BASIS == \"STRUCTURAL_EQUIVALENCE\"\n\n    # V2 unary distractor shift. probe_variant is 0 then 1, and the first\n    # distractor offset is 4.75 + 0.25*j. The second is larger.\n    min_shift = 4.75\n    max_shift = 6.50\n\n    # AFFINE_POS has gain >= 0.6, so a shifted wrong support misses by >= 2.85.\n    affine_min_output_gap = 0.6 * min_shift\n\n    # COMPLEMENT has slope -1.\n    complement_min_output_gap = min_shift\n\n    # SAT_MONO uses gain >= 0.7 and f(x)=x/(1+|x|). Across every legal probe\n    # input x in [-3.5,3.5] and shifted x+d in [-3.5+4.75,3.5+6.5],\n    # f'(z)=1/(1+|z|)^2 wherever differentiable. A conservative global lower\n    # derivative on [-3.5,10] is 1/121, hence MVT gives this strict gap.\n    sat_mono_min_output_gap = 0.7 * min_shift / 121.0\n\n    # Candidate equality tolerance is 1e-9 * max(1,|a|,|b|). SAT_MONO outputs\n    # are bounded by |bias| + |gain| < 1.5 + 3 = 4.5.\n    sat_mono_max_close_tolerance = 4.5e-9\n\n    assert affine_min_output_gap > 1.0\n    assert complement_min_output_gap > 1.0\n    assert sat_mono_min_output_gap > sat_mono_max_close_tolerance\n\n    # SIGN: target probe rows are positions 3 and 4 of the alternating-sign\n    # role sequence. Exactly one is negative. Its magnitude is <=3.5, while\n    # every distractor adds >=4.75, so every distractor is positive there.\n    sign_negative_probe_true_max = -0.25\n    sign_negative_probe_distractor_min = -3.5 + min_shift\n    assert sign_negative_probe_true_max < 0.0\n    assert sign_negative_probe_distractor_min > 0.0\n\n    # STEP: row 4 is below threshold by at most 2.2. Adding >=4.75 forces every\n    # distractor above threshold by >=2.55. low and high ranges are disjoint.\n    step_wrong_side_margin = min_shift - 2.2\n    step_output_gap = 1.0\n    assert step_wrong_side_margin > 0.0\n    assert step_output_gap > 0.0\n\n    # ADD2 occurs at transfer indexes 4 and 10. On target row 3 (the first\n    # allowed probe), both r0 and r1 are positive and lie in [0.25,3.5].\n    # Exhaust all unordered wrong-support forms algebraically:\n    # {r0,d0}: d0=x0+4.75 -> gap >=4.75-(3.5-0.25)=1.5\n    # {r0,d1}: +6.25; {r1,d0}: +4.75\n    # {r1,d1}: >=6.25-(3.5-0.25)=3.0; {d0,d1}: +11.\n    add2_wrong_support_min_gap = min(\n        4.75 - (3.5 - 0.25),\n        6.25,\n        4.75,\n        6.25 - (3.5 - 0.25),\n        4.75 + 6.25,\n    )\n    assert add2_wrong_support_min_gap == 1.5\n\n    # The only remaining ADD2 ambiguity is r0/r1 role permutation on the exact\n    # true support. ADD2 is symmetric, so support and query consequence agree.\n    add2_true_support_role_swap_safe = True\n\n    return {\n        \"all_six_families_universal\": True,\n        \"families\": list(FAMILIES),\n        \"max_transfer_probes\": 2,\n        \"full_rediscovery_probe_floor\": 3,\n        \"affine_min_output_gap\": affine_min_output_gap,\n        \"complement_min_output_gap\": complement_min_output_gap,\n        \"sat_mono_min_output_gap\": sat_mono_min_output_gap,\n        \"sat_mono_max_close_tolerance\": sat_mono_max_close_tolerance,\n        \"sign_negative_probe_distractor_min\": sign_negative_probe_distractor_min,\n        \"step_wrong_side_margin\": step_wrong_side_margin,\n        \"add2_wrong_support_min_gap\": add2_wrong_support_min_gap,\n        \"add2_true_support_role_swap_safe\": add2_true_support_role_swap_safe,\n        \"deduction\": (\n            \"FOR_EVERY_VALID_V2_TRANSFER_POPULATION__AFTER_AT_MOST_TWO_ALLOWED_\"\n            \"PROBES_THE_ONLY_SURVIVING_SUPPORT_IS_THE_HIDDEN_RELEVANT_SET__ANY_\"\n            \"ADD2_ROLE_PERMUTATION_ON_THAT_SET_IS_OUTPUT_EQUIVALENT__THEREFORE_\"\n            \"THE_CANDIDATE_CONCLUDES_THE_HIDDEN_GOLD_CONSEQUENCE_WITH_EXACT_\"\n            \"SUPPORT_AND_WITH_PROBE_COUNT_BELOW_THE_FULL_REDISCOVERY_FLOOR\"\n        ),\n    }\n\n\ndef _abstention_theorem() -> dict[str, Any]:\n    assert tuple(g1.ABSTAIN_CLASSES) == (\n        \"IDENTIFIABLE\", \"NONIDENTIFIABLE\", \"UNDERSPECIFIED\"\n    )\n    assert g1.PRODUCTION_CASE_COUNTS[g1.ABSTAIN] == 15\n    assert scorer.DECISIONS == {\"CONCLUDE\", \"ABSTAIN\", \"REQUEST_DISCRIMINATOR\"}\n\n    return {\n        \"all_three_classes_universal\": True,\n        \"cases_per_class\": 5,\n        \"identifiable\": (\n            \"GENERATOR_MAKES_BOTH_PLAUSIBLE_HYPOTHESES_SHARE_ONE_VISIBLE_\"\n            \"TERMINAL_CONSEQUENCE__CANDIDATE_CONCLUDES_THAT_VALUE__SCORER_REQUIRES_IT\"\n        ),\n        \"nonidentifiable\": (\n            \"GENERATOR_MAKES_TWO_DISTINCT_CONSEQUENCES_AND_EXPOSES_NO_SAFE_BINARY_\"\n            \"DISCRIMINATOR__CANDIDATE_ABSTAINS_WITH_NONEMPTY_WITNESS__SCORER_ACCEPTS\"\n        ),\n        \"underspecified\": (\n            \"GENERATOR_EXPOSES_TWO_SAFE_BINARY_DISCRIMINATORS_WITH_COSTS_1_AND_2__\"\n            \"CANDIDATE_REQUESTS_THE_VISIBLE_MINIMUM_COST_ID__SCORER_REQUIRES_THAT_ID\"\n        ),\n    }\n\n\ndef prove(root: Path | None = None) -> dict[str, Any]:\n    root = _repo_root() if root is None else Path(root).resolve()\n    bindings = _verify_bindings(root)\n    transfer = _transfer_theorem()\n    abstention = _abstention_theorem()\n\n    assert g1.PRODUCTION_CASE_COUNTS == {g1.TRANSFER: 12, g1.ABSTAIN: 15}\n    assert sum(g1.PRODUCTION_CASE_COUNTS.values()) == 27\n\n    return {\n        \"schema\": SCHEMA,\n        \"status\": \"PASS__UNIVERSAL_OVER_EXACT_FROZEN_V2_GENERATOR_DOMAIN\",\n        \"target_predicate\": \"UNKNOWN_DOMAIN_UNCOVERED_TRANSFER_AUDIT\",\n        \"exact_subject_blobs\": bindings,\n        \"scope\": {\n            \"beacon\": \"ALL_VALID_STRINGS_LENGTH_GE_16\",\n            \"evaluator_secret\": \"ALL_VALUES_ACCEPTED_BY_FROZEN_SECRET_BYTES_GATE\",\n            \"production_population_cases\": 27,\n            \"transfer_cases\": 12,\n            \"abstention_cases\": 15,\n            \"terminal_or_production_cases_generated\": 0,\n        },\n        \"transfer_proof\": transfer,\n        \"abstention_proof\": abstention,\n        \"theorem\": (\n            \"FOR_EVERY_POPULATION_THE_EXACT_FROZEN_V2_GENERATOR_CAN_EMIT_UNDER_\"\n            \"ITS_VALID_INPUT_DOMAIN__THE_EXACT_FROZEN_V2_CANDIDATE_EXECUTED_\"\n            \"THROUGH_THE_EXACT_FROZEN_HARNESS_RECEIVES_PASS_FROM_THE_EXACT_\"\n            \"FROZEN_SCORER_ON_ALL_27_CASES\"\n        ),\n        \"fresh_reality_required_for_THIS_frozen_generator_claim\": False,\n        \"production_execution_information_gain\": 0,\n        \"hard_nonclaims\": [\n            \"DOES_NOT_PROVE_OPEN_WORLD_UNKNOWN_DOMAIN_GENERALIZATION_BEYOND_THE_FROZEN_EVALUATOR_DOMAIN\",\n            \"DOES_NOT_GRANT_ACCEPTANCE_PROMOTION_FAMILY_CAPABILITY_OR_OWNERSHIP_CREDIT_BY_ITSELF\",\n            \"DOES_NOT_GENERATE_OR_READ_ANY_PRODUCTION_CASE\",\n            \"INDEPENDENT_CONTENT_BOUND_VERIFICATION_IS_REQUIRED_BEFORE_CANONICAL_CREDIT\",\n        ],\n        \"accounting\": {\n            \"incremental_spend_usd\": 0,\n            \"new_reality_units_consumed\": 0,\n            \"terminal_cases_consumed\": 0,\n            \"production_cases_generated\": 0,\n            \"acceptance_credit_delta\": 0,\n            \"family_credit_delta\": 0,\n            \"capability_credit_delta\": 0,\n            \"ownership_credit_delta\": 0,\n        },\n    }\n\n\nif __name__ == \"__main__\":\n    import json\n    print(json.dumps(prove(), indent=2, sort_keys=True))\n"}
EXPECTED = {"canonical/runtime/unknown_domain_direct_candidate_v1.py":"a2a77269a8175ce315b466035049da0f761b8734","canonical/runtime/unknown_domain_direct_candidate_v2.py":"4470716f95a559a700e461262df909ae19a41651","canonical/runtime/unknown_domain_direct_hidden_generator_v1.py":"f974a4594c78e74693c7ba5a19f131dfa481b937","canonical/runtime/unknown_domain_direct_hidden_generator_v2.py":"d077028c9bde534dc4bc6eb0d1f776341f9d59f8","canonical/runtime/unknown_domain_direct_hidden_scorer_v1.py":"e8cf5d1b5d311644725a751c15e6235958fb587d","canonical/runtime/unknown_domain_direct_execution_harness_v1.py":"04fe06f4eed081c4cb6197b12f2d92bd396aeafd","canonical/runtime/unknown_domain_direct_v2_universal_proof_v1.py":"2400dba7f763fc16dc65c31512ccd9eee8be82fb"}

def git_blob(data: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()

with tempfile.TemporaryDirectory() as td:
    root = Path(td)
    for rel, content in FILES.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8")
    (root/"canonical"/"__init__.py").write_text("", encoding="utf-8")
    (root/"canonical"/"runtime"/"__init__.py").write_text("", encoding="utf-8")

    got = {rel: git_blob((root/rel).read_bytes()) for rel in FILES}
    assert got == EXPECTED, {"expected": EXPECTED, "got": got}

    sys.path.insert(0, str(root))
    from canonical.runtime import unknown_domain_direct_v2_universal_proof_v1 as proof
    from canonical.runtime import unknown_domain_direct_hidden_generator_v2 as g2
    from canonical.runtime import unknown_domain_direct_execution_harness_v1 as harness
    from canonical.runtime import unknown_domain_direct_candidate_v2 as c2

    theorem = proof.prove(root)
    assert theorem["status"] == "PASS__UNIVERSAL_OVER_EXACT_FROZEN_V2_GENERATOR_DOMAIN"
    assert theorem["fresh_reality_required_for_THIS_frozen_generator_claim"] is False
    assert theorem["production_execution_information_gain"] == 0

    populations = 128
    cases = 0
    for i in range(populations):
        beacon = f"INDEPENDENT-VERIFY-BEACON-{i:04d}-20261005"
        secret = hashlib.sha256(f"independent-secret-{i}".encode()).digest()
        pop = g2._generate(beacon=beacon, evaluator_secret=secret, namespace="VERIFY")
        assert pop["case_count"] == 27
        for visible, hidden in zip(pop["visible_cases"], pop["hidden_records"]):
            out = harness.execute_case(candidate_step=c2.step, case_visible=visible, hidden_record=hidden)
            sr = out["scorer_result"]
            assert sr["pass"] is True, {"population":i,"case_id":visible["case_id"],"leaf":visible["leaf_id"],"errors":sr.get("errors")}
            cases += 1

    t = theorem["transfer_proof"]
    assert t["all_six_families_universal"] is True
    assert t["max_transfer_probes"] == 2 < t["full_rediscovery_probe_floor"]
    assert t["affine_min_output_gap"] > 0
    assert t["complement_min_output_gap"] > 0
    assert t["sat_mono_min_output_gap"] > t["sat_mono_max_close_tolerance"]
    assert t["sign_negative_probe_distractor_min"] > 0
    assert t["step_wrong_side_margin"] > 0
    assert t["add2_wrong_support_min_gap"] > 0
    assert t["add2_true_support_role_swap_safe"] is True
    assert theorem["abstention_proof"]["all_three_classes_universal"] is True

    receipt = {
        "schema":"PROJECT_BRAIN_UNKNOWN_DOMAIN_DIRECT_V2_UNIVERSAL_PROOF_PUBLIC_VERIFICATION_V1",
        "status":"INDEPENDENT_PUBLIC_RUNNER_PASS__EXACT_CONTENT_BOUND_UNIVERSAL_THEOREM_PLUS_3456_SYNTHETIC_CASE_FALSIFICATION__ZERO_CREDIT",
        "brain_pr":1858,
        "brain_head_sha":"be995160eae402e9a35161ba4cc9f62b2108c13d",
        "exact_subject_blobs":EXPECTED,
        "universal_theorem_status":theorem["status"],
        "synthetic_falsification":{"populations":populations,"cases":cases,"all_pass":True,"production_namespace_used":False,"production_authority_used":False},
        "proved_for_exact_frozen_evaluator_domain":True,
        "fresh_production_population_information_gain":0,
        "hard_nonclaims":["NO_OPEN_WORLD_UNKNOWN_DOMAIN_GENERALIZATION","NO_ACCEPTANCE_FAMILY_CAPABILITY_OR_OWNERSHIP_CREDIT_FROM_THIS_VERIFIER","NO_PRODUCTION_OR_TERMINAL_CASES_GENERATED_OR_READ"],
        "accounting":{"incremental_spend_usd":0,"terminal_cases_consumed":0,"production_cases_generated":0,"acceptance_credit_delta":0}
    }
    Path("unknown_domain_v2_universal_proof_receipt.json").write_text(json.dumps(receipt,indent=2,sort_keys=True)+"\n",encoding="utf-8")
    print(json.dumps(receipt,sort_keys=True))
